mapping=dict(line.split('|',1) for line in beats.splitlines())
mapping.update(pilots)
prefix='Eight-second premium miniature physical comedy. Animate the EXACT painted geometric sculpture in the starting photograph using whole-object translation and rotation, like stop-motion of one solid artwork. Its irregular silhouette, colored blocks and existing flat graphic inlays remain the SAME attached geometry throughout. Every currently blank surface stays blank. This existing single-piece sculpture is the subject of the following action: '
suffix=' The sculpture itself visibly changes position and angle relative to the set. Give each hop clear lift and a grounded landing with contact shadow; movements are small and physically weighted. Keep its original decorated front toward the locked camera. Same setting, light and materials. One continuous shot. Preserve the photographed abstract design, with no new eyes, face, text, human limbs, transformation, people or cuts.'
episodes=[]
for e in old['episodes']:
    n=e['id'];assert n in mapping
    episodes.append({'id':n,'title_ko':e['title_ko'],'keyframe':f'episode-{n}-keyframe.png','motion':mapping[n],'prompt':prefix+mapping[n].replace('SOULI','the sculpture')+suffix,'status':'planned'})
(p/'production-plan.json').write_text(json.dumps({'version':2,'date':'2026-10-03','purpose':'Remake all 80 approved scenes with visible SOULI agency, preserving approved keyframes and old finals.','qa':['SOULI itself visibly translates, hops or tilts relative to set','Existing silhouette and graphic patches stay recognizable throughout','Clear setup, reaction and comic payoff','No added human limbs, facial replacements or obvious object teleportation','Full file decode plus 16 sampled frames and motion playback when uncertain'],'episodes':episodes},ensure_ascii=False,indent=2),encoding='utf-8')
print('Prepared',len(episodes),'scene-specific motion remakes.')
